/**
 * @param {Uint8Array} bytes
 * @param {number} start
 * @param {number} quote
 * @returns {{end: number, closed: boolean}}
 */
function scanString(bytes, start, quote) {
  let pos = start + 1;
  while (pos < bytes.length) {
    const b = bytes[pos];
    if (b === 0x5c) {
      pos += 2;
